const temporaryDirectories = [];

/**
 * Creates a temporary directory that is removed after the current test.
 * @returns {Promise<string>} The directory path.
 */
async function createTempDir() {
	const directory = await fs.mkdtemp(path.join(os.tmpdir(), "eslint-api-"));
	temporaryDirectories.push(directory);
	return directory;
}

/**
 * Creates an ESLint instance with an inline flat config file.
 * @param {string} cwd The working directory.
 * @param {object} [extraOptions] Additional ESLint options.
 * @returns {ESLint} The ESLint instance.
 */
function createESLint(cwd, extraOptions = {}) {
	return new ESLint({
		cwd,
		overrideConfigFile: true,
		overrideConfig: { rules: {} },
		...extraOptions,
	});
}

/**
 * Creates a deprecated rule whose `create()` reports on the Program node.
 * @param {boolean} newFormat Whether to use the newer object form of `deprecated`.
 * @returns {object} A rule definition.
 */
function createDeprecatedRule(newFormat) {
	return {
		meta: {
			type: "problem",
			deprecated: newFormat
				? {
					message: "Use the replacement rule.",
					replacedBy: [
						{
							plugin: { name: "eslint-plugin-example" },
							rule: { name: "replacement" },
						},
						{ rule: { name: "plain-replacement" } },
					],
				}
				: true,
			replacedBy: newFormat ? void 0 : ["plain-replacement"],
			schema: [],
		},
		create(context) {
			return {
				Program(node) {
					context.report({ node, message: "Deprecated rule ran." });
				},
			};
		},
	};
}

