/**
 * Attaches `parent` properties to every node of the AST, the way ESLint does
 * while traversing source code.
 * @param {Object} node The node to start from.
 * @param {Object|null} parent The parent node.
 * @returns {void}
 */
function attachParents(node, parent) {
	node.parent = parent;

	for (const key of VISITOR_KEYS[node.type] || []) {
		const child = node[key];

		if (Array.isArray(child)) {
			for (const item of child) {
				if (item && typeof item.type === "string") {
					attachParents(item, node);
				}
			}
		} else if (child && typeof child.type === "string") {
			attachParents(child, node);
		}
	}
}

/**
 * Parses code and returns everything a test may need: the AST (with parent
 * pointers), a SourceCode instance (with scope info) and the scope manager.
 * @param {string} code The code to parse.
 * @param {Object} [overrides] Overrides for the espree parse options.
 * @returns {{ast: Object, sourceCode: SourceCode, scopeManager: Object}} Parsed info.
 */
function parse(code, overrides = {}) {
	const options = { ...PARSE_OPTIONS, ...overrides };
	const ast = espree.parse(code, options);

	attachParents(ast, null);

	const scopeManager = eslintScope.analyze(ast, {
		ecmaVersion: 2026,
		sourceType: options.sourceType,
		ignoreEval: true,
	});

	const sourceCode = new SourceCode({
		text: code,
		ast,
		scopeManager,
		visitorKeys: VISITOR_KEYS,
	});

	return { ast, sourceCode, scopeManager };
}

/**
 * Depth first walk over all nodes.
 * @param {Object} node The node to start from.
 * @param {Function} callback Called for every node.
 * @returns {void}
 */
function walk(node, callback) {
	callback(node);

	for (const key of VISITOR_KEYS[node.type] || []) {
		const child = node[key];

		if (Array.isArray(child)) {
			for (const item of child) {
				if (item && typeof item.type === "string") {
					walk(item, callback);
				}
			}
		} else if (child && typeof child.type === "string") {
