			["isNotClosingBracketToken", "isClosingBracketToken", "]"],
			["isNotClosingParenToken", "isClosingParenToken", ")"],
			["isNotColonToken", "isColonToken", ":"],
			["isNotCommaToken", "isCommaToken", ","],
			["isNotDotToken", "isDotToken", "."],
			["isNotQuestionDotToken", "isQuestionDotToken", "?."],
			["isNotOpeningBraceToken", "isOpeningBraceToken", "{"],
			["isNotOpeningBracketToken", "isOpeningBracketToken", "["],
			["isNotOpeningParenToken", "isOpeningParenToken", "("],
			["isNotSemicolonToken", "isSemicolonToken", ";"],
		];

		for (const [negatedName, positiveName, value] of negations) {
			const negated = astUtils[negatedName];
			const positive = astUtils[positiveName];
			const matching = { type: "Punctuator", value };
			const notMatching = { type: "Identifier", value: "foo" };

