// -----------------------------------------------------------------------------
// Static value helpers
// -----------------------------------------------------------------------------

describe("skipChainExpression", () => {
	const { ast } = parse("a?.b; a.b;");

	test("returns the wrapped expression of a ChainExpression", () => {
		const chain = getNode(ast, "ChainExpression");

		expect(astUtils.skipChainExpression(chain)).toBe(chain.expression);
		expect(astUtils.skipChainExpression(chain).type).toBe("MemberExpression");
	});

	test("passes through other nodes", () => {
		const member = getNode(ast, "MemberExpression");

		expect(astUtils.skipChainExpression(member)).toBe(member);
		expect(astUtils.skipChainExpression(undefined)).toBeUndefined();
	});
});

describe("getStaticStringValue", () => {
	const { ast } = parse(
		'"foo"; 100; 1.5; true; false; null; /a/gu; 1n; `${"baz"}`; `qux${x}`; [1]; foo;',
	);
	const [
		stringLiteral,
		numberLiteral,
		floatLiteral,
		trueLiteral,
		falseLiteral,
		nullLiteral,
		regexLiteral,
		bigintLiteral,
	] = collectNodes(ast, "Literal");
	const [staticTemplate, dynamicTemplate] = collectNodes(
		ast,
		"TemplateLiteral",
	);

	test("converts literal values to their string representation", () => {
		expect(astUtils.getStaticStringValue(stringLiteral)).toBe("foo");
		expect(astUtils.getStaticStringValue(numberLiteral)).toBe("100");
		expect(astUtils.getStaticStringValue(floatLiteral)).toBe("1.5");
		expect(astUtils.getStaticStringValue(trueLiteral)).toBe("true");
		expect(astUtils.getStaticStringValue(falseLiteral)).toBe("false");
		expect(astUtils.getStaticStringValue(nullLiteral)).toBe("null");
	});

	test("converts regular expression literals to their source form", () => {
		expect(astUtils.getStaticStringValue(regexLiteral)).toBe("/a/gu");
	});

	test("converts bigint literals to their digits", () => {
		expect(astUtils.getStaticStringValue(bigintLiteral)).toBe("1");
	});

	test("returns the cooked value of template literals without expressions", () => {
		expect(astUtils.getStaticStringValue(staticTemplate)).toBe("baz");
	});

	test("returns null when the value cannot be determined statically", () => {
		expect(astUtils.getStaticStringValue(dynamicTemplate)).toBeNull();
		expect(
			astUtils.getStaticStringValue(
				findNode(
					ast,
					node => node.type === "Identifier" && node.name === "foo",
				),
			),
		).toBeNull();
