		["a()", "CallExpression", 18],
		["a?.b", "ChainExpression", 18],
		['import("m")', "ImportExpression", 18],
		["new A()", "NewExpression", 19],
		["a", "Identifier", 20],
		["({})", "ObjectExpression", 20],
	])("returns %i for %s", (code, type, expected) => {
		const { ast } = parse(code);

		expect(astUtils.getPrecedence(findNode(ast, node => node.type === type))).toBe(
			expected,
		);
	});

	test.each([
		["a || b", "||", 4],
		["a ?? b", "??", 4],
		["a && b", "&&", 5],
	])("returns %i for logical operator %s", (code, operator, expected) => {
		const { ast } = parse(code);

		expect(
			astUtils.getPrecedence(
				findNode(
					ast,
					node =>
						node.type === "LogicalExpression" &&
						node.operator === operator,
				),
			),
		).toBe(expected);
	});

	test.each([
		["a | b", "|", 6],
		["a ^ b", "^", 7],
		["a & b", "&", 8],
		["a == b", "==", 9],
		["a !== b", "!==", 9],
		["a < b", "<", 10],
		["a instanceof b", "instanceof", 10],
		["a in b", "in", 10],
		["a << b", "<<", 11],
		["a >> b", ">>", 11],
		["a >>> b", ">>>", 11],
		["a + b", "+", 12],
		["a - b", "-", 12],
		["a * b", "*", 13],
		["a / b", "/", 13],
		["a % b", "%", 13],
		["a ** b", "**", 15],
	])("returns %i for binary operator %s", (code, operator, expected) => {
		const { ast } = parse(code);

		expect(
			astUtils.getPrecedence(
				findNode(
					ast,
					node =>
						node.type === "BinaryExpression" &&
						node.operator === operator,
				),
			),
		).toBe(expected);
	});

	test("returns -1 for unknown node types", () => {
		expect(astUtils.getPrecedence({ type: "UnknownNode" })).toBe(-1);
	});
});

// -----------------------------------------------------------------------------
// Literal classification
// -----------------------------------------------------------------------------

describe("isDecimalInteger", () => {
	const code = [
		"0",
		"5",
		"50",
		"5_000",
		"1_234_56",
		"08",
		"0192",
		"5.",
		".5",
		"5.0",
		"05",
		"0x5",
		"0b101",
		"0o5",
		"5e0",
		"5n",
		'"5"',
	].join("; ");
	const { ast } = parse(code, { sourceType: "script" });
	const literals = collectNodes(ast, "Literal");
	const byRaw = new Map(literals.map(literal => [literal.raw, literal]));

	test.each([
		["0", true],
		["5", true],
		["50", true],
		["5_000", true],
		["1_234_56", true],
		["08", true],
		["0192", true],
		["5.", false],
		[".5", false],
		["5.0", false],
		["05", false],
		["0x5", false],
		["0b101", false],
		["0o5", false],
		["5e0", false],
		["5n", false],
		['"5"', false],
	])("returns %p for the literal %s", (raw, expected) => {
		expect(byRaw.has(raw)).toBe(true);
		expect(astUtils.isDecimalInteger(byRaw.get(raw))).toBe(expected);
	});
});

describe("isDecimalIntegerNumericToken", () => {
	const { ast } = parse("0; 5; 5_000; 0x5; 5e0; 5n; 5.0; \"5\";");
	const numericTokens = ast.tokens.filter(token => token.type === "Numeric");
	const byValue = new Map(numericTokens.map(token => [token.value, token]));

	test.each([
		["0", true],
		["5", true],
		["5_000", true],
		["0x5", false],
		["5e0", false],
		["5n", false],
		["5.0", false],
	])("returns %p for the numeric token %s", (value, expected) => {
		expect(byValue.has(value)).toBe(true);
		expect(astUtils.isDecimalIntegerNumericToken(byValue.get(value))).toBe(
			expected,
		);
	});

	test("returns false for tokens that are not numeric", () => {
		const stringToken = ast.tokens.find(token => token.type === "String");

		expect(astUtils.isDecimalIntegerNumericToken(stringToken)).toBe(false);
	});
});

// -----------------------------------------------------------------------------
// Directives and statements
// -----------------------------------------------------------------------------

describe("getDirectivePrologue", () => {
	test("returns the leading directives of a program", () => {
		const { ast } = parse(
			'"use strict";\n"use asm";\nfoo();\n"not a directive";',
		);

		expect(astUtils.getDirectivePrologue(ast)).toEqual([
			ast.body[0],
			ast.body[1],
		]);
	});

	test("returns the leading directives of a function body", () => {
		const { ast } = parse(
			'function f() { "use strict"; foo(); }',
		);
		const func = getNode(ast, "FunctionDeclaration");

		expect(astUtils.getDirectivePrologue(func)).toEqual([
			func.body.body[0],
		]);
	});

	test("returns the leading directives of an arrow function with a block body", () => {
		const { ast } = parse('() => { "use strict"; };');
		const arrow = getNode(ast, "ArrowFunctionExpression");

		expect(astUtils.getDirectivePrologue(arrow)).toEqual([
			arrow.body.body[0],
		]);
	});

	test("returns an empty array when there is no directive prologue", () => {
		const { ast } = parse("foo();");

		expect(astUtils.getDirectivePrologue(ast)).toEqual([]);

		const { ast: arrowAst } = parse('() => "use strict";');

		expect(
			astUtils.getDirectivePrologue(
				getNode(arrowAst, "ArrowFunctionExpression"),
			),
		).toEqual([]);
	});
});

describe("isDirective", () => {
	test("accepts expression statements in a directive prologue", () => {
		const { ast } = parse('"use strict";');

		expect(astUtils.isDirective(ast.body[0])).toBe(true);
	});

	test("rejects parenthesised strings and other statements", () => {
		const { ast } = parse('("use strict"); foo(); var a = 1;');

		expect(astUtils.isDirective(ast.body[0])).toBe(false);
		expect(astUtils.isDirective(ast.body[1])).toBe(false);
		expect(astUtils.isDirective(ast.body[2])).toBe(false);
	});
});

describe("isTopLevelExpressionStatement", () => {
	const { ast } = parse(
		"foo();\nif (a) { bar(); }\nfunction f() { baz(); }\n{ qux(); }\nvar v;",
	);
	const identifiers = name =>
		findNode(ast, node => node.type === "Identifier" && node.name === name);
	const expressionStatementOf = name =>
		identifiers(name).parent.type === "ExpressionStatement"
			? identifiers(name).parent
			: identifiers(name).parent.parent;

	test("accepts expression statements at the top level of a program", () => {
		expect(astUtils.isTopLevelExpressionStatement(expressionStatementOf("foo"))).toBe(
			true,
		);
	});

	test("accepts expression statements directly inside a function body", () => {
		expect(
			astUtils.isTopLevelExpressionStatement(expressionStatementOf("baz")),
		).toBe(true);
	});

	test("rejects expression statements in nested blocks", () => {
		expect(
			astUtils.isTopLevelExpressionStatement(expressionStatementOf("bar")),
		).toBe(false);
		expect(
			astUtils.isTopLevelExpressionStatement(expressionStatementOf("qux")),
		).toBe(false);
	});

	test("rejects nodes that are not expression statements", () => {
		expect(
			astUtils.isTopLevelExpressionStatement(
				getNode(ast, "VariableDeclaration"),
			),
		).toBe(false);
	});
});

describe("isStartOfExpressionStatement", () => {
	const { ast } = parse("foo();\n(a);\nb + (c);\nd.e;");

	test("returns true for nodes that start an expression statement", () => {
		expect(
			astUtils.isStartOfExpressionStatement(
				findNode(ast, node => node.type === "Identifier" && node.name === "foo"),
			),
		).toBe(true);
		expect(
			astUtils.isStartOfExpressionStatement(
				findNode(ast, node => node.type === "Identifier" && node.name === "d"),
			),
		).toBe(true);
		expect(
			astUtils.isStartOfExpressionStatement(
				findNode(
					ast,
					node =>
						node.type === "BinaryExpression" && node.operator === "+",
				),
			),
		).toBe(true);
	});

	test("returns false for nodes that start later than the statement", () => {
		expect(
			astUtils.isStartOfExpressionStatement(
				findNode(ast, node => node.type === "Identifier" && node.name === "a"),
			),
		).toBe(false);
		expect(
			astUtils.isStartOfExpressionStatement(
				findNode(ast, node => node.type === "Identifier" && node.name === "c"),
			),
		).toBe(false);
	});
});

describe("isEmptyBlock", () => {
	test("accepts empty block statements", () => {
		const { ast } = parse("{}");

		expect(astUtils.isEmptyBlock(getNode(ast, "BlockStatement"))).toBe(true);
	});

	test("rejects blocks with statements and other nodes", () => {
		const { ast } = parse("{ foo(); }");

		expect(astUtils.isEmptyBlock(getNode(ast, "BlockStatement"))).toBe(false);
		expect(astUtils.isEmptyBlock(null)).toBe(false);
		expect(astUtils.isEmptyBlock(ast)).toBe(false);
	});
});

describe("isEmptyFunction", () => {
	test("accepts functions with empty bodies", () => {
		const { ast } = parse(
			"function foo() {} (function () {}); (() => {});",
		);

		expect(astUtils.isEmptyFunction(getNode(ast, "FunctionDeclaration"))).toBe(
			true,
		);
		expect(astUtils.isEmptyFunction(getNode(ast, "FunctionExpression"))).toBe(
			true,
		);
		expect(
			astUtils.isEmptyFunction(getNode(ast, "ArrowFunctionExpression")),
		).toBe(true);
	});

	test("rejects functions with statements or comments only bodies", () => {
		const { ast } = parse("function foo() { bar(); } (() => { /* c */ });");

		expect(astUtils.isEmptyFunction(getNode(ast, "FunctionDeclaration"))).toBe(
			false,
		);
		expect(
			astUtils.isEmptyFunction(getNode(ast, "ArrowFunctionExpression")),
		).toBe(true);
	});

	test("rejects nodes that are not functions", () => {
		const { ast } = parse("{}");

		expect(astUtils.isEmptyFunction(getNode(ast, "BlockStatement"))).toBe(
			false,
		);
	});
});
