{"command": "cd /testbed && cat >> test/lib/rules/utils/ast-utils.test.js <<'EOF'

// -----------------------------------------------------------------------------
// Automatic semicolon insertion
// -----------------------------------------------------------------------------

describe("needsPrecedingSemicolon", () => {
	/**
	 * Checks whether a node is an expression statement calling the given name.
	 * @param {Object} node The node to check.
	 * @param {string} name The expected callee name.
	 * @returns {boolean} Whether the node matches.
	 */
	function isCallTo(node, name) {
		return (
			node.type === "ExpressionStatement" &&
			node.expression.type === "CallExpression" &&
			node.expression.callee.type === "Identifier" &&
			node.expression.callee.name === name
		);
	}

	/**
	 * Checks whether a node is a variable declaration for the given name.
	 * @param {Object} node The node to check.
	 * @param {string} name The expected variable name.
	 * @returns {boolean} Whether the node matches.
	 */
	function isDeclarationOf(node, name) {
		return (
			node.type === "VariableDeclaration" &&
			node.declarations.length === 1 &&
			node.declarations[0].id.name === name
		);
	}

	/**
	 * Checks whether a node is a method definition with the given name.
	 * @param {Object} node The node to check.
	 * @param {string} name The expected method name.
	 * @returns {boolean} Whether the node matches.
	 */
	function isMethodNamed(node, name) {
		return (
			node.type === "MethodDefinition" &&
			node.key.type === "Identifier" &&
			node.key.name === name
		);
	}

	test.each([
		["foo();\nbar();", node => isCallTo(node, "foo"), false],
		["foo();\nbar();", node => isCallTo(node, "bar"), false],
		["let a = 1\nlet b = 2;", node => isDeclarationOf(node, "b"), true],
		["a\nb;", node => isCallTo(node, "b") || node.type === "ExpressionStatement", true],
		["let a\nb;", node => node.type === "ExpressionStatement", false],
		[
			"function f() { return\nfoo; }",
			node => node.type === "ExpressionStatement",
			false,
		],
		["if (a)\nfoo();", node => isCallTo(node, "foo"), false],
		["while (a)\nfoo();", node => isCallTo(node, "foo"), false],
		["for (;;)\nfoo();", node => isCallTo(node, "foo"), false],
		["do foo(); while (a)\nbaz();", node => isCallTo(node, "baz"), true],
		["if (a) { foo(); }\nbaz();", node => isCallTo(node, "baz"), false],
		["const o = { a: 1 }\nbaz();", node => isCallTo(node, "baz"), true],
		["const C = class {}\nbaz();", node => isCallTo(node, "baz"), true],
		["const f = function () {}\nbaz();", node => isCallTo(node, "baz"), true],
		["function f() {}\nbaz();", node => isCallTo(node, "baz"), false],
		["class A { }\nbaz();", node => isCallTo(node, "baz"), false],
		["class A { foo\nbar() {} }", node => isMethodNamed(node, "bar"), false],
		["class A { [foo]\nbar() {} }", node => isMethodNamed(node, "bar"), false],
		["class A { foo = 1\nbar() {} }", node => isMethodNamed(node, "bar"), true],
		['import "mod"\nfoo();', node => isCallTo(node, "foo"), false],
		['export * from "mod"\nfoo();', node => isCallTo(node, "foo"), false],
		['"str"\nfoo();', node => isCallTo(node, "foo"), true],
		["foo()\n(bar)();", node => isCallTo(node, "foo") || node.type === "ExpressionStatement", true],
	])("returns %p before the node in %s", (code, predicate, expected) => {
		const { ast, sourceCode } = parse(code);

		let node;

		try {
			node = findNode(ast, predicate);
		} catch {
			// `a\nb;` is parsed as a single statement in some cases; fall back
			// to the last statement of the program.
			node = ast.body.at(-1);
		}

		expect(astUtils.needsPrecedingSemicolon(sourceCode, node)).toBe(expected);
	});
});

// -----------------------------------------------------------------------------
// Constant expressions
// -----------------------------------------------------------------------------

describe("isConstant", () => {
	test.each([
		["1", true, true],
		["foo", false, false],
		["undefined", true, true],
		["void 0", true, true],
		["typeof foo", true, false],
		["-foo", false, false],
		["!foo", false, false],
		["!1", true, true],
		["1 + 2", true, true],
		["1 + foo", false, false],
		["[]", true, true],
		["[1]", true, true],
		["[foo]", true, false],
		["[,]", true, true],
		["`foo`", true, true],
		["`${foo}`", false, false],
		["`${1}`", false, true],
		["() => {}", true, true],
		["function () {}", true, true],
		["({})", true, true],
		["(class {})", true, true],
		["new Foo()", true, false],
		["Boolean(1)", true, true],
		["Boolean(foo)", false, false],
		["Boolean()", true, true],
		["(foo, 1)", true, true],
		["foo && false", true, false],
		["false || foo", false, false],
		["foo || true", true, false],
		["true || foo", true, true],
		["true && foo", false, false],
		["foo && bar", false, false],
		["x = 1", true, true],
		["x = foo", false, false],
		["x ||= true", true, false],
		["x &&= false", true, false],
		["x ??= true", false, false],
		["x += 1", false, false],
		["[1, ...foo]", true, false],
	])("returns %p (boolean position: %p) for %s", (code, booleanExpected, otherExpected) => {
		const { ast, sourceCode } = parse(code);
		const node = ast.body[0].expression;
		const scope = sourceCode.getScope(node);

		expect(astUtils.isConstant(scope, node, true)).toBe(booleanExpected);
		expect(astUtils.isConstant(scope, node, false)).toBe(otherExpected);
	});

	test("treats a missing node as constant", () => {
		const { ast, sourceCode } = parse("foo;");

		expect(astUtils.isConstant(sourceCode.getScope(ast), null, false)).toBe(
			true,
		);
	});

	test("treats spread elements as their argument", () => {
		const { ast, sourceCode } = parse("f(...[1]); f(...foo);");
		const [constantSpread, dynamicSpread] = collectNodes(ast, "SpreadElement");

		expect(
			astUtils.isConstant(sourceCode.getScope(constantSpread), constantSpread, false),
		).toBe(true);
		expect(
			astUtils.isConstant(sourceCode.getScope(dynamicSpread), dynamicSpread, false),
		).toBe(false);
	});

	test("recognizes the global undefined variable only", () => {
		const { ast, sourceCode } = parse(
			"function f() { return undefined; }",
		);
		const argument = getNode(ast, "ReturnStatement").argument;

		expect(
			astUtils.isConstant(sourceCode.getScope(argument), argument, true),
		).toBe(true);

		const { ast: shadowedAst, sourceCode: shadowedSourceCode } = parse(
			"function f(undefined) { return undefined; }",
		);
		const shadowedArgument = getNode(shadowedAst, "ReturnStatement").argument;

		expect(
			astUtils.isConstant(
				shadowedSourceCode.getScope(shadowedArgument),
				shadowedArgument,
				true,
			),
		).toBe(false);
	});

	test("recognizes the global Boolean function only", () => {
		const { ast: shadowedAst, sourceCode: shadowedSourceCode } = parse(
			"function f(Boolean) { return Boolean(1); }",
		);
		const call = getNode(shadowedAst, "CallExpression");

		expect(
			astUtils.isConstant(
				shadowedSourceCode.getScope(call),
				call,
				true,
			),
		).toBe(false);
	});
});

describe("isReferenceToGlobalVariable", () => {
	const { ast, sourceCode } = parse(
		"undefined;\nfoo;\nlet bar = 1;\nbar;\nfunction f() { undefined; }",
	);
	const undefinedReferences = collectNodes(ast, "Identifier").filter(
		node => node.name === "undefined",
	);
	const fooReference = findNode(
		ast,
		node => node.type === "Identifier" && node.name === "foo",
	);
	const barReference = findNode(
		ast,
		node =>
			node.type === "Identifier" &&
			node.name === "bar" &&
			node.parent.type === "ExpressionStatement",
	);

	test("accepts references to builtin global variables", () => {
		expect(
			astUtils.isReferenceToGlobalVariable(
				sourceCode.getScope(undefinedReferences[0]),
				undefinedReferences[0],
			),
		).toBe(true);
	});

	test("accepts builtin global references inside functions", () => {
		expect(
			astUtils.isReferenceToGlobalVariable(
				sourceCode.getScope(undefinedReferences[1]),
				undefinedReferences[1],
			),
		).toBe(true);
	});

	test("rejects unresolved references", () => {
		expect(
			astUtils.isReferenceToGlobalVariable(
				sourceCode.getScope(fooReference),
				fooReference,
			),
		).toBe(false);
	});

	test("rejects references to declared variables", () => {
		expect(
			astUtils.isReferenceToGlobalVariable(
				sourceCode.getScope(barReference),
				barReference,
			),
		).toBe(false);
	});

	test("rejects identifiers that are not references in the given scope", () => {
		expect(
			astUtils.isReferenceToGlobalVariable(
				sourceCode.getScope(fooReference),
				undefinedReferences[0],
			),
		).toBe(false);
	});
});

// -----------------------------------------------------------------------------
// `this` binding
// -----------------------------------------------------------------------------

describe("isDefaultThisBinding", () => {
	test.each([
		["function foo() {}", true],
		["function Foo() {}", false],
		["function Foo() {}", true, { capIsConstructor: false }],
		["({ foo: function () {} });", false],
		["({ foo() {} });", false],
		["class A { foo() {} }", false],
		["class A { foo = function () {}; }", false],
		["class A { foo = () => {}; }", false],
		["const foo = function () {};", true],
		["const Foo = function () {};", false],
		["const Foo = function () {};", true, { capIsConstructor: false }],
		["const foo = function bar() {};", true],
		["obj.foo = function () {};", false],
		["foo = function () {};", true],
		["Foo = function () {};", false],
		["Foo = function () {};", true, { capIsConstructor: false }],
		["var foo = function () {}.bind(obj);", false],
		["var foo = function () {}.bind(null);", true],
		["var foo = function () {}.bind();", true],
		["(function foo() {}).call(obj);", false],
		["Reflect.apply(function () {}, obj, []);", false],
		["Reflect.apply(function () {}, null, []);", true],
		["Array.from([], function () {}, obj);", false],
		["Array.from([], function () {});", true],
		["[1].forEach(function () {}, obj);", false],
		["[1].forEach(function () {});", true],
		["(() => {})();", true],
		["() => {};", true],
		["/** @this */ function foo() {}", false],
		["foo(/* @this sinon.Sandbox */ function () {});", false],
		["function foo() { return function () {}; }", true],
	])("returns %p for %s", (code, expected, options) => {
		const { ast, sourceCode } = parse(code);
		const func = getFirstFunction(ast);
		const actual = options
			? astUtils.isDefaultThisBinding(func, sourceCode, options)
			: astUtils.isDefaultThisBinding(func, sourceCode);

		expect(actual).toBe(expected);
	});

	test("returns false for static blocks", () => {
		const { ast, sourceCode } = parse("class A { static {} }");

		expect(
			astUtils.isDefaultThisBinding(
				getNode(ast, "StaticBlock"),
				sourceCode,
			),
		).toBe(false);
	});

	test("follows the return value of an immediately invoked function", () => {
		const { ast, sourceCode } = parse(
			"var Foo = (function () { return function () {}; })();",
		);
		const innerFunction = findNode(
			ast,
			node =>
				node.type === "FunctionExpression" &&
				node.parent.type === "ReturnStatement",
		);

		expect(astUtils.isDefaultThisBinding(innerFunction, sourceCode)).toBe(
			false,
		);

		const { ast: lowerAst, sourceCode: lowerSourceCode } = parse(
			"var foo = (function () { return function () {}; })();",
		);
		const innerLowerFunction = findNode(
			lowerAst,
			node =>
				node.type === "FunctionExpression" &&
				node.parent.type === "ReturnStatement",
		);

		expect(
			astUtils.isDefaultThisBinding(innerLowerFunction, lowerSourceCode),
		).toBe(true);
	});

	test("follows the return value of an immediately invoked arrow function", () => {
		const { ast, sourceCode } = parse(
			"var Foo = (() => function () {})();",
		);
		const innerFunction = findNode(
			ast,
			node =>
				node.type === "FunctionExpression" &&
				node.parent.type === "ArrowFunctionExpression",
		);

		expect(astUtils.isDefaultThisBinding(innerFunction, sourceCode)).toBe(
			false,
		);
	});

	test("follows logical expressions assigned to object properties", () => {
		const { ast, sourceCode } = parse(
			"obj.foo = cond || function () {};",
		);

		expect(
			astUtils.isDefaultThisBinding(getFirstFunction(ast), sourceCode),
		).toBe(false);
	});
});
